args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film (MIN(xsd:date(?bd)) AS ?earliestDirectorBirth) WHERE {
  VALUES ?film { dbr:Our_Crazy_Aunts dbr:Dearest_(2014_film) }
  ?film dbo:director ?dir .
  { ?dir dbo:birthDate ?bd } UNION { ?dir dbp:birthDate ?bd }
}
GROUP BY ?film
ORDER BY ?earliestDirectorBirth
LIMIT 1

